def esc(s): return s.replace("\\", "\\\\").replace('"', '\\"')
def write(path, table, i):
    with open(path, "w", encoding="utf-8") as f:
        f.write("/* Generated by gen_strings.py. Edit the table there, not here. */\n\n")
        for k, v in table.items():
            f.write(f'"{k}" = "{esc(v[i])}";\n')
for i, lang in enumerate(L):
    d = os.path.join(root, f"{lang}.lproj"); os.makedirs(d, exist_ok=True)
    write(os.path.join(d, "Localizable.strings"), T, i)
    write(os.path.join(d, "InfoPlist.strings"), INFO, i)
print(f"{len(T)} UI keys, {len(INFO)} Info.plist keys × {len(L)} languages")
